-- 0008 voided tickets and task completion time. Generated by drizzle-kit from src/db/schema.ts, then:
--   [hand-edit 1] attendees.cancelled_at is readable by owner/admin like the other non-secret attendee columns
--                 (0006 grants attendee SELECT column by column; qr_uuid stays unreadable). No write privilege.
--   [hand-edit 2] tasks.completed_at follows the status for every writer: set when a task becomes DONE (unless
--                 the writer set it), cleared when it leaves DONE. Browser roles may only write tasks.status
--                 (0003), so without this a task moved to DONE on the board never got a completion time.
ALTER TABLE "attendees" ADD COLUMN "cancelled_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "attendees" ADD CONSTRAINT "attendees_cancelled_not_checked_in" CHECK ("attendees"."cancelled_at" is null or not "attendees"."is_checked_in");--> statement-breakpoint
GRANT SELECT ("cancelled_at") ON "attendees" TO "authenticated";--> statement-breakpoint
CREATE FUNCTION app.tasks_track_completion() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF NEW.status = 'DONE' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    NEW.completed_at := coalesce(NEW.completed_at, now());
  ELSIF NEW.status <> 'DONE' THEN
    NEW.completed_at := NULL;
  END IF;
  RETURN NEW;
END
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app.tasks_track_completion() FROM PUBLIC;--> statement-breakpoint
CREATE TRIGGER "tasks_track_completion" BEFORE INSERT OR UPDATE OF "status" ON "tasks" FOR EACH ROW EXECUTE FUNCTION app.tasks_track_completion();
